<div class="p-3"><div class="d-flex justify-content-between"><div><span class="eyebrow">Especialista #<?= (int)$especialista['especialista_id'] ?></span><h3 class="h5 mb-1"><?= htmlspecialchars($especialista['nome']) ?></h3><div class="text-muted small"><?= htmlspecialchars($especialista['nome_profissional'] ?: 'Nome profissional não informado') ?></div></div><span class="ops-badge <?= (int)$especialista['aprovado']?'ops-badge--service':'ops-badge--new' ?>"><?= (int)$especialista['aprovado']?'Aprovado':'Pendente' ?></span></div><hr><dl class="row small"><dt class="col-5">E-mail</dt><dd class="col-7"><?= htmlspecialchars($especialista['email']) ?></dd><dt class="col-5">Telefone</dt><dd class="col-7"><?= htmlspecialchars($especialista['telefone'] ?: '—') ?></dd><dt class="col-5">Serviços</dt><dd class="col-7"><?= htmlspecialchars($especialista['servicos'] ?: 'Nenhum') ?></dd><dt class="col-5">Raio</dt><dd class="col-7"><?= htmlspecialchars((string)$especialista['raio_atendimento_km']) ?> km</dd></dl>
