<hr><h4 class="h6">Evidências recentes</h4><?php foreach(($especialista['evidencias']??[]) as $ev): $m=json_decode((string)$ev['metadata_json'],true)?:[]; ?><div class="d-flex justify-content-between align-items-center small border-top py-2"><span><?= htmlspecialchars($ev['evento']) ?> · <?= htmlspecialchars($ev['criado_em']) ?></span><?php if(!empty($m['arquivo'])): ?><a class="btn btn-sm btn-outline-warning" target="_blank" href="<?= BASE_PATH ?>/evidencia-especialista/<?= (int)$ev['id'] ?>">Ver foto</a><?php endif; ?></div><?php endforeach; ?>
<hr><h4 class="h6">Financeiro</h4><?php if(empty($especialista['financeiro'])): ?><div class="small text-muted">Nenhum lançamento.</div><?php else: foreach($especialista['financeiro'] as $f): ?><div class="d-flex justify-content-between border-top py-2 small"><span><?= htmlspecialchars(str_replace('_',' ',(string)$f['tipo'])) ?></span><span>R$ <?= number_format((float)$f['valor'],2,',','.') ?> · <?= htmlspecialchars($f['status']) ?></span></div><?php endforeach; endif; ?></div>
